package pe.edu.upeu.pago.entity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime; @Entity @Table(name="ordenes_certificado") @Getter @Setter @NoArgsConstructor public class OrdenCertificado { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="inscripcion_id",nullable=false) private Long inscripcionId; @Column(name="estudiante_id",nullable=false) private Long estudianteId; @Column(name="curso_id",nullable=false) private Long cursoId; @Column(name="docente_id",nullable=false) private Long docenteId; @Column(name="monto_total",nullable=false,precision=10,scale=2) private BigDecimal montoTotal; @Column(name="comision_kido",nullable=false,precision=10,scale=2) private BigDecimal comisionKido; @Column(name="monto_docente",nullable=false,precision=10,scale=2) private BigDecimal montoDocente; @Enumerated(EnumType.STRING) @Column(nullable=false,length=24) private EstadoOrden estado; @Column(name="mp_preference_id",length=120) private String mercadoPagoPreferenceId; @Column(name="mp_payment_id",length=120,unique=true) private String mercadoPagoPaymentId; @Column(name="fecha_creacion",nullable=false) private LocalDateTime fechaCreacion; @Column(name="fecha_aprobacion") private LocalDateTime fechaAprobacion; public enum EstadoOrden{PENDIENTE,PAGO_INICIADO,APROBADA,RECHAZADA} }